"""Cuaderno del estudiante, 5.º básico Lenguaje y Comunicación, OA 04 (análisis profundo de narraciones).

Todos los textos son originales y breves; cada ejercicio trae el texto que necesita.
"""
from __future__ import annotations

from student_content_le5_a import E, L, n_words
from student_lessons import arith

OA4 = "LE05 OA 04"

BILLETERA = "Tomás encontró una billetera con dinero cerca del kiosco. Dudó un momento, porque quería comprar un balón. Pero vio una credencial dentro, caminó hasta el kiosco y preguntó a la dueña si conocía al dueño. Cuando el señor llegó, Tomás le entregó la billetera. El señor le ofreció una recompensa y Tomás la rechazó, aunque sus manos temblaban un poco."
BICI = "Lucas dejó su bicicleta en el patio y no la guardó. Esa noche llovió mucho. A la mañana siguiente, el asiento estaba empapado y las ruedas llenas de barro. Lucas tuvo que ir caminando a la escuela y llegó tarde. Por eso se perdió la explicación del profesor y no pudo hacer bien la tarea. Desde ese día, guarda su bicicleta cada tarde."
CALETA = "Era una mañana de invierno en una caleta del sur. Las casas de madera tenían techos de zinc y de las chimeneas salía humo. En la orilla, unos pescadores reparaban redes mientras otros vecinos secaban pescado al viento. Los domingos, todos se juntaban en la feria del muelle a intercambiar pescados, papas y lana."
ELVIRA = "Doña Elvira era pequeña y caminaba algo encorvada, pero siempre iba rápido. Era muy terca: cuando decidía algo, nadie la hacía cambiar de idea. Un día todos dijeron que el puente colgante estaba dañado y que no debían cruzar. Doña Elvira, sin embargo, dijo que la sopa para su vecina enferma no podía esperar y empezó a cruzar. A mitad del puente, una tabla crujió y ella tuvo que volver, muy asustada."
TEXTO_A = "A. Esa tarde llovía en el pueblo. Rosa miraba por la ventana cómo el agua llenaba las calles. Su perro Canelo no volvía. Rosa tomó su impermeable, salió a buscarlo y lo encontró en la plaza, empapado, jugando con otro perro. Los dos volvieron a casa."
TEXTO_B = "B. La lluvia golpeaba los vidrios como un tambor impaciente. Rosa sintió que el corazón se le encogía: Canelo no estaba. Salió corriendo, con el miedo pisándole los talones. En la plaza lo vio, tiritando y alegre, y lo abrazó tan fuerte que casi se le escapa el alma de felicidad."
AMBOS = TEXTO_A + " " + TEXTO_B
FARO = "Nico vivía junto al faro y cada noche subía a encender la luz. Una noche el viento apagó la lámpara y una tormenta cubrió el mar. Nico, con las manos temblorosas, volvió a encenderla tres veces hasta que quedó prendida. Al amanecer, el pescador Ramón le contó que su bote había encontrado el camino gracias a esa luz. Desde entonces, Nico dejó de tener miedo a las tormentas y se sintió orgulloso de su tarea."

L(OA4, 1,
  "Este cuaderno, lápiz y las oraciones escritas en cada ejercicio.",
  "Aprenderé a interpretar el lenguaje figurado en una narración: comparación, metáfora, personificación, hipérbole y expresiones con sentido distinto del literal.",
  ["Leo narraciones con comprensión.", "Sé que las palabras pueden decir más de lo que parece."],
  ["El lenguaje figurado usa las palabras con un sentido distinto del literal para decir algo de manera más viva. La comparación une dos cosas con «como» o «igual que»: «Corría como el viento». La metáfora dice que algo es otra cosa: «Sus ojos eran dos faroles». La personificación da rasgos humanos a lo que no es persona: «El viento susurraba».",
   "La hipérbole es una exageración: «Te llamé mil veces». Las expresiones con sentido figurado, como «estar en las nubes» o «tener un corazón de oro», no se entienden palabra por palabra: «estar en las nubes» quiere decir estar distraído, y «corazón de oro», ser muy bueno.",
   "Para interpretar una expresión figurada, pregúntate qué quiere decir en esa historia. Si tomas la frase literalmente y no tiene sentido, es figurada. Luego busca qué rasgo se destaca: velocidad, tamaño, cariño, miedo. Así entiendes mejor cómo es el personaje o cómo se siente."],
  [("lenguaje figurado", "uso de palabras con sentido distinto del literal"), ("metáfora", "figura que dice que una cosa es otra"), ("personificación", "figura que da rasgos humanos a lo que no es persona"), ("hipérbole", "exageración para destacar algo")],
  [("Interpretar una comparación", "«Mi hermano corre como el viento». ¿Qué quiere destacar?", ["Compara a mi hermano con el viento.", "El viento es muy veloz.", "Quiere decir que corre muy rápido."], "Que corre muy rápido"),
   ("Interpretar una expresión", "«Se me hizo un nudo en la garganta». ¿Qué siente quien lo dice?", ["Un nudo real en la garganta no tiene sentido.", "Es una expresión figurada.", "Significa que sintió mucha emoción o ganas de llorar."], "Mucha emoción o ganas de llorar")],
  [("Tomar la expresión al pie de la letra.", "Se interpreta cada palabra literalmente.", "Pregunta qué quiere decir en la historia."), ("Confundir comparación con metáfora.", "Las dos relacionan cosas.", "Si usa «como» o «igual que» es comparación; si dice que algo «es» otra cosa, es metáfora.")],
  ([E("«Corría como el viento». ¿Es comparación o metáfora?", "Comparación", "Usa «como» para unir dos cosas."),
    E("«Sus ojos eran dos faroles encendidos». ¿Es comparación o metáfora?", "Metáfora", "Dice que los ojos «eran» faroles."),
    E("«El viento susurraba secretos». ¿Qué figura le da rasgos humanos al viento?", "Personificación", "Un viento no susurra como una persona.")],
   [E("«Mi tía tiene un corazón de oro». ¿Qué quiere decir: que es muy buena o que su corazón es de metal?", "Que es muy buena", "Es una expresión figurada para una persona generosa."),
    E("«Te llamé mil veces». ¿Es exageración (hipérbole) o dato exacto?", "Exageración", "Destaca que llamó muchas veces."),
    E("«Estaba en las nubes y no escuchó». ¿Qué le pasaba: estaba volando o estaba distraído?", "Estaba distraído", "Es una expresión figurada.")],
   [E("«La luna nos miraba desde el cielo». ¿Qué figura es?", "Personificación", "La luna no mira como una persona."),
    E("«Su sonrisa era un sol». ¿Qué destaca de la sonrisa: que alegra e ilumina a quienes la ven o que quema la piel?", "Que alegra e ilumina", "El sol ilumina y da calor; la metáfora destaca la alegría que transmite."),
    E("«Hace una eternidad que espero». ¿Qué figura es?", "Hipérbole", "Exagera el tiempo de espera.")],
   [E("Dos niños interpretan «Tiene piernas de rayo»: Ana dice que corre muy rápido y Beto que tiene piernas eléctricas. ¿Quién interpreta bien?", "Ana", "Es una metáfora que destaca la rapidez."),
    E("Un cuento dice: «El silencio era una piedra pesada». ¿Qué sensación crea: tranquilidad o tensión?", "Tensión", "Una piedra pesada sugiere algo incómodo.")],
   [E("Lees: «Las olas, enojadas, golpeaban el muelle como puños». Nombra una personificación y una comparación.", "Personificación: olas enojadas; comparación: como puños", "El enojo es humano; «como puños» usa «como»."),
    E("«Lloró un mar de lágrimas». ¿Es una exageración o un hecho literal?", "Una exageración", "Nadie llora un mar.")]),
  [E("En una carta, Julia escribe: «Mi abuelo es un roble». Si el roble es fuerte y firme, ¿qué quiere decir de su abuelo?", "Que es fuerte y firme", "La metáfora le da esas cualidades.")],
  [E("¿Con qué palabra suele empezar una comparación?", "Con «como»", "Une dos cosas."),
   E("¿Qué figura da rasgos humanos a lo que no es persona?", "La personificación", "Hace actuar a objetos o fenómenos como personas."),
   E("¿Qué figura exagera para destacar algo?", "La hipérbole", "Como «mil veces».")],
  ("Lee estas cuatro oraciones y escribe, de cada una, qué figura es y qué quiere decir: 1) «El viento susurraba secretos.» 2) «Tengo mil tareas.» 3) «Sus manos eran hielo.» 4) «Se movía como una tortuga.» Luego inventa una oración con una de estas figuras sobre tu lugar favorito.", "1) Personificación: el viento suena suave. 2) Hipérbole: tiene muchas tareas. 3) Metáfora: tenía las manos muy frías. 4) Comparación: era muy lento. Oración: «La plaza me abraza con sus árboles» (personificación).", ["identifica cada figura", "explica el sentido", "inventa una oración con sentido figurado"], ["cuatro respuestas", "oración propia"], ["tomar la figura literalmente", "no explicar el sentido"], "Pide a otra persona que interprete tu oración y compara."),
  "Busca en un cuento tres expresiones figuradas y explica qué quieren decir.",
  "Escribe un párrafo de tres líneas sobre un día de lluvia con una comparación y una personificación.")

L(OA4, 2,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a opinar sobre las actitudes y acciones de los personajes y a fundamentar mi opinión con ejemplos del texto.",
  ["Reconozco personajes y sus acciones.", "Distingo un hecho de una opinión."],
  ["Una actitud es la manera de comportarse ante una situación, como ser honesto, valiente o generoso. Las acciones son lo que el personaje hace. Al leer, podemos dar una opinión sobre si lo que hizo estuvo bien o mal, o si nos parece admirable o poco justo. La opinión es personal, pero debe apoyarse en el texto.",
   "Para fundamentar una opinión sigue tres pasos: primero, dices tu opinión; segundo, usas «porque»; tercero, das un ejemplo del texto. Por ejemplo: «Tomás fue honesto porque devolvió la billetera aunque quería comprar un balón». Sin el ejemplo, la opinión queda en el aire.",
   "Una buena opinión también considera lo que el personaje sentía. En el texto, Tomás dudó y le temblaban las manos: eso muestra que no fue fácil. Dos lectores pueden opinar distinto, pero ambos deben mostrar en qué parte del texto se basan."],
  [("actitud", "manera de comportarse ante una situación"), ("opinión", "lo que alguien piensa o siente sobre algo"), ("fundamentar", "apoyar lo que se dice con razones y ejemplos"), ("honesto", "que dice la verdad y actúa con rectitud")],
  [("Opinión con ejemplo", f"Lees: «{BILLETERA}» Opina sobre Tomás con un ejemplo del texto.", ["Mi opinión: Tomás fue honesto.", "Uso «porque» y busco un ejemplo.", "Devolvió la billetera aunque quería comprar un balón."], "Tomás fue honesto porque devolvió la billetera aunque quería un balón"),
   ("Opinión sin fundamento", "«Tomás me cae bien.» ¿Qué le falta?", ["Es una opinión.", "No dice por qué.", "Falta «porque» y un ejemplo del texto."], "Una razón con ejemplo")],
  [("Dar una opinión sin ejemplos del texto.", "Se cree que basta decir lo que uno piensa.", "Agrega «porque» y un hecho del texto."), ("Inventar hechos que el texto no dice.", "Se quiere reforzar la opinión.", "Usa solo lo que está en el texto.")],
  ([E(BILLETERA + " Según el texto, ¿qué hizo Tomás con la billetera?", "La entregó a su dueño", "Lo dice el texto."),
    E(BILLETERA + " Tomás dudó porque quería comprar algo. ¿Qué quería comprar?", "Un balón", "Lo dice la segunda oración."),
    E("¿Qué es una actitud: una manera de comportarse o un objeto?", "Una manera de comportarse", "Se ve en lo que el personaje hace.")],
   [E("Una buena opinión se dice con: (a) «porque» y un ejemplo del texto o (b) solo «me gusta».", "(a)", "Fundamentar es dar razones del texto."),
    E(BILLETERA + " ¿Qué muestran las manos temblorosas de Tomás: que no sentía nada o que le costó rechazar la recompensa?", "Que le costó rechazar la recompensa", "Los temblores muestran emoción y esfuerzo."),
    E("¿Dos lectores pueden opinar distinto sobre un personaje si ambos se basan en el texto?", "Sí", "Lo importante es mostrar en qué parte se apoyan.")],
   [E(BILLETERA + " Completa con el verbo que usa el texto: «Tomás fue honesto porque le ___ la billetera al señor».", "entregó", "El texto dice «Tomás le entregó la billetera»."),
    E(BILLETERA + " ¿Cuál es un ejemplo del texto que muestra que Tomás fue honesto: «caminó hasta el kiosco y preguntó por el dueño» o «tenía un balón viejo»?", "«caminó hasta el kiosco y preguntó por el dueño»", "Es una acción del texto que lo muestra."),
    E(BILLETERA + " Si opinas que Tomás fue desinteresado (no actuó buscando un premio), ¿cuál es el ejemplo?", "La rechazó aunque sus manos temblaban", "Rechazó algo que le convenía.")],
   [E(BILLETERA + " Ana dice «Tomás es bueno». Beto dice «Tomás es honesto porque devolvió la billetera». ¿Quién fundamenta mejor?", "Beto", "Da una razón con ejemplo."),
    E(BILLETERA + " Una lectora dice «Tomás no fue honesto porque no devolvió la billetera». ¿Su opinión coincide con el texto?", "No", "El texto dice que la devolvió.")],
   [E(BILLETERA + " Un lector opina «Tomás debió aceptar la recompensa, porque la merecía». ¿Es válida si da razones del texto?", "Sí, si da razones del texto", "La opinión puede ser distinta si se fundamenta."),
    E(BILLETERA + " Un lector dice «Tomás fue deshonesto porque dudó un momento». ¿Está bien fundamentada su opinión?", "No", "Al final devolvió la billetera, y eso es lo que muestra su honestidad.")]),
  [E("En tu curso, un compañero encuentra un cuaderno y lo devuelve a su dueño. Para fundamentar que fue honesto, ¿qué ejemplo usarías?", "Que lo devolvió a su dueño", "Es la acción que lo demuestra.")],
  [E("¿Qué palabra ayuda a fundamentar una opinión?", "Porque", "Introduce la razón."),
   E("¿Qué se debe dar después de «porque»?", "Un ejemplo del texto", "Apoya la opinión."),
   E("¿Las acciones de un personaje son lo que hace o lo que dice el autor?", "Lo que hace", "Se leen en el texto.")],
  (f"Lee: «{BILLETERA}» Escribe tu opinión sobre la actitud de Tomás en tres frases: tu opinión, «porque» y un ejemplo del texto. Después escribe una opinión distinta posible, también fundamentada.", "Mi opinión: Tomás fue honesto porque devolvió la billetera aunque quería un balón. Otra opinión: Tomás debió aceptar la recompensa porque devolver la billetera le costó esfuerzo; el texto dice que dudó y que le temblaban las manos.", ["opina sobre la actitud", "usa «porque»", "da un ejemplo del texto", "propone otra opinión fundamentada"], ["dos opiniones fundamentadas"], ["opinar sin ejemplo", "inventar hechos"], "Subraya el ejemplo del texto que usaste en cada opinión."),
  "Elige un personaje de un cuento y opina sobre él con «porque» y un ejemplo.",
  "Escribe la opinión de un personaje distinto sobre las mismas acciones de Tomás.")

L(OA4, 3,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a determinar las consecuencias de hechos y acciones en una narración, y a distinguir causa y consecuencia.",
  ["Entiendo el orden de los hechos.", "Sé qué es una causa."],
  ["En una narración, lo que ocurre se conecta. La causa es lo que hace que algo suceda; la consecuencia es lo que sucede después como resultado. Si Lucas no guarda su bicicleta y llueve, la causa es dejarla afuera y la consecuencia es que se moja.",
   "Una consecuencia puede provocar otra: la bicicleta mojada obliga a caminar, caminar hace llegar tarde y llegar tarde hace perder la explicación. Así se forma una cadena. Palabras como «por eso», «así que», «entonces» y «como resultado» ayudan a reconocer consecuencias.",
   "Para determinar una consecuencia, pregunta: ¿qué pasó después de esta acción y por qué? Revisa que lo que anotas esté en el texto o se deduzca de él. Muchas veces los personajes cambian por las consecuencias, como Lucas, que aprende a guardar su bicicleta."],
  [("causa", "lo que hace que algo ocurra"), ("consecuencia", "lo que ocurre como resultado de una causa"), ("cadena de hechos", "serie de hechos conectados uno tras otro"), ("conector causal", "palabra o frase que une una causa con su consecuencia")],
  [("Una consecuencia directa", f"Lees: «{BICI}» ¿Qué consecuencia tuvo dejar la bicicleta en el patio?", ["La causa: no la guardó y llovió.", "Qué pasó después: el asiento quedó empapado y las ruedas con barro.", "Esa es la consecuencia directa."], "El asiento quedó empapado y las ruedas con barro"),
   ("Una cadena de consecuencias", "Ordena: (a) llegó tarde (b) la bicicleta estaba mojada (c) se perdió la explicación.", ["Primero la bicicleta mojada (b).", "Por eso caminó y llegó tarde (a).", "Por eso se perdió la explicación (c)."], "b, a, c")],
  [("Confundir causa con consecuencia.", "Se invierte el orden.", "La causa ocurre primero; la consecuencia, después."), ("Anotar consecuencias que el texto no sugiere.", "Se imagina de más.", "Apóyate en lo escrito.")],
  ([E(BICI + " En el texto de Lucas, ¿qué hizo Lucas el día anterior que luego causó problemas?", "Dejó la bicicleta en el patio", "No la guardó y la lluvia la mojó."),
    E(BICI + " ¿Qué le pasó a la bicicleta durante la noche?", "Se mojó con la lluvia", "Llovió mucho toda la noche."),
    E("¿Qué es una consecuencia: lo que ocurre después como resultado o lo que causa algo?", "Lo que ocurre después como resultado", "Es el efecto de una causa.")],
   [E(BICI + " ¿Por qué Lucas llegó tarde a la escuela?", "Porque tuvo que ir caminando", "No pudo usar la bicicleta mojada."),
    E(BICI + " ¿Qué consecuencia tuvo llegar tarde?", "Se perdió la explicación del profesor", "Por eso no pudo hacer bien la tarea."),
    E("En «Por eso se perdió la explicación», ¿qué conector muestra una consecuencia?", "Por eso", "Une la causa con su resultado.")],
   [E(BICI + " ¿Qué cambio hubo en Lucas después de la experiencia?", "Guarda su bicicleta cada tarde", "Aprendió de la consecuencia."),
    E("Completa la cadena: no guardó la bici → ___ → llegó tarde. (a) la bici se mojó y tuvo que caminar, (b) ganó un premio.", "(a)", "La bicicleta mojada lo obligó a caminar."),
    arith("Si cada vez que dejara la bicicleta afuera caminara 15 minutos más, y le ocurriera 3 días seguidos, ¿cuántos minutos extra caminaría en total?", "15*3", "Se multiplican los minutos extra por los días.")],
   [E("Ana dice que llegar tarde fue la causa de que la bici se mojara. ¿Está bien?", "No", "La bici se mojó primero; llegar tarde fue consecuencia."),
    E("Si Lucas hubiera guardado la bicicleta, ¿qué consecuencia habría evitado: el asiento empapado o la lluvia?", "El asiento empapado", "La lluvia no depende de él.")],
   [E("Un personaje cuenta un secreto sin permiso y su amigo deja de confiar en él. ¿Cuál es la consecuencia?", "Su amigo deja de confiar en él", "Es lo que ocurre como resultado."),
    E("Con la cadena «no estudió → sacó mala nota → se sintió triste», ¿cuántas consecuencias hay después de la primera acción?", "2", "Las consecuencias son sacar mala nota y sentirse triste.")]),
  [E("Un niño olvida avisar que no irá a una práctica y sus compañeros lo esperan mucho rato. ¿Cuál es la consecuencia: (a) sus compañeros perdieron tiempo esperándolo o (b) el niño olvidó avisar?", "(a)", "Perder tiempo ocurre después; olvidar avisar es la causa.")],
  [E("En Lenguaje: ¿Qué es una causa?", "Lo que hace que algo ocurra", "Es el origen del hecho."),
   E("¿Qué conector muestra consecuencia: «por eso» o «pero»?", "Por eso", "Une causa y resultado."),
   E("¿Una acción puede tener varias consecuencias?", "Sí", "Una lleva a otra y forma una cadena.")],
  (f"Lee: «{BICI}» Escribe una cadena con tres flechas que muestre las consecuencias de dejar la bicicleta afuera. Luego explica qué cambió en Lucas.", "No guardó la bicicleta → se mojó y se llenó de barro → fue caminando → llegó tarde y se perdió la explicación. Lucas aprendió a guardar su bicicleta cada tarde.", ["escribe la cadena en orden", "usa conectores", "explica el cambio del personaje"], ["una cadena", "una explicación"], ["invertir causa y consecuencia", "agregar hechos que no están"], "Revisa cada flecha: ¿la primera causa la segunda?"),
  "Elige un cuento y escribe una cadena de tres hechos conectados por «por eso».",
  "Inventa un hecho con tres consecuencias en cadena.")

L(OA4, 4,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a describir el ambiente y las costumbres que aparecen en una narración, usando pistas del texto.",
  ["Sé quiénes son los personajes de una narración.", "Distingo lugar y tiempo."],
  ["El ambiente es el lugar y el tiempo donde ocurre la historia, y también la atmósfera que se siente. El lugar puede ser un pueblo, una caleta o una ciudad. El tiempo puede ser la época o el momento: una mañana de invierno. Las pistas están en las descripciones: casas de madera, humo en las chimeneas, redes en la orilla.",
   "Las costumbres son las formas habituales de vivir de un grupo: lo que hacen cada día, sus fiestas, su manera de trabajar o de juntarse. Si el texto dice que los domingos todos se juntan en la feria, esa es una costumbre del lugar. Las costumbres nos muestran cómo era la vida de esas personas.",
   "Para describir el ambiente, subraya las palabras que indican lugar, tiempo y cosas del entorno. Para las costumbres, busca lo que los personajes hacen siempre o en fechas especiales. Después explica con tus palabras cómo imaginas ese lugar y por qué."],
  [("ambiente", "lugar, tiempo y atmósfera en que ocurre una historia"), ("costumbre", "forma habitual de hacer algo en un grupo"), ("caleta", "pequeña bahía donde viven y trabajan pescadores"), ("atmósfera", "sensación que transmite un lugar o una escena")],
  [("Describir el ambiente", f"Lees: «{CALETA}» ¿Dónde y cuándo ocurre la historia?", ["Busco el lugar: una caleta del sur.", "Busco el tiempo: una mañana de invierno.", "Respondo con ambos datos."], "En una caleta del sur, una mañana de invierno"),
   ("Identificar costumbres", "En el mismo texto, ¿qué costumbre de los domingos se menciona?", ["Busco 'los domingos'.", "Dice que todos se juntan en la feria del muelle.", "Allí intercambian pescados, papas y lana."], "Juntarse en la feria del muelle a intercambiar productos")],
  [("Confundir el ambiente con los personajes.", "Se miran solo las personas.", "El ambiente es el lugar, el tiempo y lo que lo rodea."), ("Inventar costumbres que el texto no menciona.", "Se supone cómo es el lugar.", "Usa solo las pistas del texto.")],
  ([E(CALETA + " En el texto de la caleta, ¿en qué estación del año ocurre?", "En invierno", "Lo dice la primera oración."),
    E(CALETA + " ¿De qué material eran las casas?", "De madera", "El texto dice «casas de madera»."),
    E(CALETA + " ¿Qué hacían unos pescadores en la orilla?", "Reparaban redes", "Lo dice el texto.")],
   [E(CALETA + " ¿Qué hacían otros vecinos mientras unos pescadores reparaban redes?", "Secaban pescado al viento", "Está en la tercera oración."),
    E("¿Qué es una costumbre: una forma habitual de hacer algo o un objeto?", "Una forma habitual de hacer algo", "Se repite en un grupo."),
    E(CALETA + " ¿Qué pista muestra que hacía frío: el humo en las chimeneas o el zinc de los techos?", "El humo en las chimeneas", "Se usa la chimenea para calentarse.")],
   [E(CALETA + " ¿Qué se intercambia en la feria del muelle?", "Pescados, papas y lana", "Está en la última oración."),
    E(CALETA + " ¿Qué día de la semana se juntan en la feria?", "Domingo", "El texto dice «los domingos»."),
    arith("Si 4 familias llevan 3 sacos de papas cada una a la feria, ¿cuántos sacos hay?", "4*3", "Se multiplican las familias por los sacos de cada una.")],
   [E(CALETA + " Un lector dice que la historia ocurre en una ciudad grande. ¿Qué pista del texto lo contradice: «una caleta del sur» o «una mañana de invierno»?", "«una caleta del sur»", "Una caleta es un lugar pequeño de pescadores, no una ciudad grande."),
    E(CALETA + " ¿Qué costumbre muestra que la comunidad colabora: intercambiar productos en la feria o dormir temprano?", "Intercambiar productos en la feria", "Se ayudan e intercambian lo que producen.")],
   [E("Imagina otra caleta donde los jueves hay una fiesta con música. ¿Es una costumbre o un hecho que ocurrió una sola vez?", "Una costumbre", "Ocurre cada jueves."),
    E(CALETA + " ¿Qué sensación transmite el ambiente del texto: calma de trabajo diario o peligro?", "Calma de trabajo diario", "Describe tareas cotidianas y una feria.")]),
  [E("Describe tu escuela con una pista de lugar y una de tiempo: «En un edificio de dos pisos, a las 8 de la mañana». ¿Qué parte indica el tiempo?", "A las 8 de la mañana", "Indica el momento.")],
  [E("En una narración, ¿qué abarca el ambiente: lugar, tiempo y atmósfera, o solo los personajes?", "El lugar, el tiempo y la atmósfera", "Rodea a los personajes."),
   E("¿Qué son las costumbres?", "Formas habituales de vivir de un grupo", "Son hábitos que se repiten."),
   E("¿Las pistas del ambiente están en las descripciones del texto?", "Sí", "Señalan lugar, tiempo y entorno.")],
  (f"Lee: «{CALETA}» Escribe: 1) dos pistas del lugar; 2) dos pistas del tiempo; 3) dos costumbres. Luego escribe cómo imaginas la vida en esa caleta usando esas pistas.", "1) Casas de madera; techos de zinc. 2) Mañana de invierno; domingos. 3) Reparar redes y secar pescado; juntarse en la feria. Imagino una vida de trabajo en comunidad.", ["escribe pistas de lugar", "escribe pistas de tiempo", "describe costumbres", "imagina con base en el texto"], ["seis pistas", "descripción breve"], ["inventar datos", "confundir ambiente con personajes"], "Subraya en el texto cada pista que usaste."),
  "Lee un cuento y anota tres pistas de su ambiente y una costumbre.",
  "Describe en cuatro líneas el ambiente de tu barrio por la mañana, con dos costumbres.")

L(OA4, 5,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a explicar las características físicas y psicológicas de los personajes que importan para el desarrollo de la historia.",
  ["Sé quién es el personaje principal.", "Describo cómo es una persona."],
  ["Un personaje tiene características físicas, como su altura, su manera de caminar o su aspecto, y características psicológicas, que se escriben también «sicológicas»: su manera de ser, como terco, valiente, tímido o generoso. Las físicas se ven; las psicológicas se deducen de lo que piensa, dice y hace.",
   "No todas las características importan igual. Las relevantes son las que influyen en lo que ocurre. Que doña Elvira sea terca importa, porque por eso cruza el puente aunque le advierten del peligro. Que sea pequeña importa menos, porque no cambia lo que pasa.",
   "Para explicar una característica psicológica, usa la estructura: «El personaje es ___ porque ___ (ejemplo del texto)». Después di cómo esa característica influye en la historia. Así conectas al personaje con los hechos."],
  [("característica física", "rasgo que se ve en el aspecto del personaje"), ("característica psicológica", "rasgo de la manera de ser del personaje; también se escribe «sicológica»"), ("terco", "que no cambia de idea aunque le adviertan"), ("relevante", "importante para entender lo que ocurre")],
  [("Una característica psicológica", f"Lees: «{ELVIRA}» ¿Cómo es doña Elvira por dentro?", ["Busco cómo actúa: no cambia de idea.", "El texto dice que es muy terca.", "Su ejemplo: cruza el puente aunque le advierten."], "Es terca"),
   ("Una característica relevante", "¿Qué importa más para la historia: que sea pequeña o que sea terca?", ["Pienso en lo que ocurre: cruza el puente.", "Lo hace por su terquedad.", "La terquedad cambia la historia; su estatura no."], "Que sea terca")],
  [("Decir solo cómo es el personaje por fuera.", "Se describe lo que se ve.", "Añade cómo es por dentro con ejemplos."), ("Nombrar una característica sin ejemplo.", "Se cree que es obvio.", "Usa «porque» y una acción del texto.")],
  ([E(ELVIRA + " Según el texto, ¿cómo era doña Elvira de tamaño?", "Pequeña", "Lo dice la primera oración."),
    E(ELVIRA + " ¿«Terca» es una característica física o psicológica?", "Psicológica", "Habla de su manera de ser."),
    E(ELVIRA + " ¿Qué hizo doña Elvira aunque le advirtieron?", "Empezó a cruzar el puente", "Lo hizo por su terquedad.")],
   [E(ELVIRA + " ¿«Caminaba algo encorvada» es una característica física o psicológica?", "Física", "Se ve en su aspecto."),
    E(ELVIRA + " ¿Por qué quiso cruzar el puente?", "Para llevar sopa a su vecina enferma", "El texto lo dice."),
    E(ELVIRA + " ¿Qué característica psicológica muestra llevar sopa a una vecina enferma: generosidad o pereza?", "Generosidad", "Se preocupa por otra persona.")],
   [E(ELVIRA + " Completa: «Doña Elvira es terca porque ___».", "cuando decidía algo nadie la hacía cambiar", "El texto lo dice expresamente."),
    E(ELVIRA + " ¿Qué característica psicológica la llevó a quedar sobre un puente dañado: su terquedad o su estatura?", "Su terquedad", "Por ella cruzó el puente dañado."),
    E(ELVIRA + " ¿Qué muestra que doña Elvira también era prudente al final: que volvió al sentir el crujido o que siguió cruzando?", "Que volvió al sentir el crujido", "Reaccionó ante el peligro.")],
   [E(ELVIRA + " Ana dice que la estatura de doña Elvira fue clave en el hecho. Beto dice que su terquedad. ¿Quién tiene razón según el texto?", "Beto", "La terquedad la llevó a cruzar."),
    E(ELVIRA + " Si doña Elvira no fuera terca y hubiera hecho caso, ¿habría cruzado el puente?", "No", "La advertencia la habría detenido.")],
   [E(ELVIRA + " Si doña Elvira fuera muy tímida, ¿cambiaría la historia? Elige: (a) sí, porque no habría desobedecido a todos, (b) no, porque la historia es igual.", "(a)", "La terquedad impulsa el conflicto."),
    E("Doña Elvira «era muy terca». ¿Qué ejemplo del texto lo respalda: «caminaba algo encorvada» o «dijo que la sopa no podía esperar y empezó a cruzar»?", "«dijo que la sopa no podía esperar y empezó a cruzar»", "Es una acción: cruza aunque todos le advierten. Caminar encorvada es un rasgo físico.")]),
  [E("En tu curso hay un compañero que siempre ayuda a otros con las tareas. ¿Qué característica psicológica muestra esa acción: generosidad o egoísmo?", "Generosidad", "Ayuda sin pedir nada a cambio.")],
  [E("¿Cómo se llama el rasgo de la manera de ser?", "Característica psicológica", "También se escribe «sicológica»."),
   E("¿Cuál es relevante en una historia: la que influye en los hechos o cualquiera?", "La que influye en los hechos", "Explica lo que ocurre."),
   E("¿Qué se usa para mostrar cómo es un personaje por dentro: sus acciones o su estatura?", "Sus acciones", "De ellas se deduce su manera de ser.")],
  (f"Lee: «{ELVIRA}» Escribe: 1) una característica física; 2) dos psicológicas con un ejemplo del texto cada una; 3) cuál influye más en la historia y por qué.", "1) Es pequeña y algo encorvada. 2) Terca: cruzó pese a la advertencia. Generosa: llevaba sopa a su vecina enferma. 3) La terquedad, porque por ella cruzó el puente y se asustó.", ["nombra una física", "da dos psicológicas con ejemplo", "explica cuál influye más"], ["tres respuestas"], ["describir solo el aspecto", "no dar ejemplos"], "Pide a otra persona que diga cuál característica influye más y compara."),
  "Elige un personaje de un cuento y escribe una característica física y una psicológica con ejemplo.",
  "Describe a un personaje inventado cuya timidez cambie el final de una historia.")

L(OA4, 6,
  "Este cuaderno, lápiz y los dos textos escritos en esta clase.",
  "Aprenderé a comparar dos textos de autores distintos y a justificar cuál prefiero con razones y ejemplos.",
  ["Interpreto lenguaje figurado.", "Opino con ejemplos del texto."],
  ["Dos autores pueden contar la misma historia de forma distinta. Para compararlos, mira varios aspectos: el lenguaje (sencillo o con figuras), el narrador, cómo muestran las emociones del personaje, el ambiente y la manera de terminar. Compara lo mismo en ambos textos, no cosas distintas.",
   "Una comparación se escribe con conectores como «mientras que», «en cambio» y «a diferencia de». Por ejemplo: «El texto A cuenta los hechos sin figuras, en cambio el texto B usa comparaciones». También se puede decir en qué se parecen: ambos cuentan que Rosa busca a su perro.",
   "Preferir un texto es una opinión legítima, pero debe justificarse. Di cuál prefieres, por qué y con qué ejemplo: «Prefiero el B porque sus comparaciones me hacen sentir la lluvia». Otra persona puede preferir el A por su claridad, y ambas opiniones son válidas si están fundamentadas."],
  [("autor", "persona que escribe un texto"), ("comparar", "buscar semejanzas y diferencias"), ("a diferencia de", "expresión para marcar una diferencia"), ("justificar", "dar razones para apoyar lo que se dice")],
  [("Encontrar una diferencia", f"Textos: «{TEXTO_A}» «{TEXTO_B}» ¿En qué se diferencia el lenguaje?", ["A cuenta los hechos de manera directa.", "B usa comparaciones y personificaciones.", "La diferencia: B usa más lenguaje figurado."], "B usa más lenguaje figurado"),
   ("Justificar una preferencia", "Prefieres el texto B. ¿Cómo justificas?", ["Digo cuál prefiero.", "Uso «porque».", "Doy un ejemplo del texto: «la lluvia golpeaba los vidrios como un tambor»."], "Prefiero el B porque sus comparaciones me hacen sentir la lluvia")],
  [("Comparar aspectos distintos en cada texto.", "Se mira lo primero que se ve.", "Elige los mismos aspectos para ambos."), ("Preferir sin dar razones.", "Se cree que basta decir cuál gusta más.", "Usa «porque» y un ejemplo.")],
  ([E(AMBOS + " En ambos textos, ¿qué busca Rosa?", "A su perro Canelo", "Los dos lo cuentan."),
    E(AMBOS + " ¿Qué texto dice que la lluvia golpeaba como un tambor?", "El texto B", "Es una comparación del texto B."),
    E(AMBOS + " ¿Dónde encuentra Rosa a Canelo en ambos textos?", "En la plaza", "Ambos textos coinciden en eso.")],
   [E(AMBOS + " ¿Qué texto usa más comparaciones y personificaciones: A o B?", "B", "Tiene «como un tambor impaciente» y «el miedo pisándole los talones»."),
    E(AMBOS + " ¿Cómo termina el texto A: con los dos volviendo a casa o con un abrazo muy fuerte?", "Con los dos volviendo a casa", "Lo dice la última oración."),
    E("¿Qué conector sirve para marcar una diferencia: «a diferencia de» o «también»?", "A diferencia de", "Marca una diferencia.")],
   [E(AMBOS + " ¿En qué se parecen los textos A y B: ambos cuentan que Rosa busca a Canelo o ambos usan comparaciones?", "Ambos cuentan que Rosa busca a Canelo", "Solo B usa comparaciones."),
    E(AMBOS + " ¿Qué sentimiento de Rosa se destaca más en B: miedo y felicidad o aburrimiento?", "Miedo y felicidad", "Dice «el corazón se le encogía» y «felicidad»."),
    E("Elige el conector que marca el contraste: «El texto A es sencillo, ___ el texto B usa lenguaje figurado». (a) en cambio (b) porque", "(a)", "«En cambio» marca una diferencia; «porque» introduce una causa.")],
   [E(AMBOS + " Ana prefiere el A porque es claro y directo. Beto prefiere el B porque le hace sentir la lluvia. ¿Hay una preferencia equivocada?", "No", "Ambas están justificadas."),
    E("Una lectora dice «Prefiero el B porque sí». ¿Está justificada?", "No", "Falta una razón con ejemplo.")],
   [E(AMBOS + " Escribe una semejanza entre A y B.", "Ambos cuentan que Rosa busca y encuentra a Canelo", "Es lo que comparten."),
    E(AMBOS + " ¿Qué texto muestra mejor la emoción de Rosa: el que usa «el corazón se le encogía» o el que dice solo «Su perro no volvía»?", "El que usa «el corazón se le encogía»", "Muestra la emoción con lenguaje figurado.")]),
  [E("Dos amigos cuentan el mismo partido de fútbol: uno solo da el marcador y el otro describe el ambiente. ¿Quién da más sensaciones?", "El que describe el ambiente", "Muestra lo que se sentía.")],
  [E("¿Qué hay que hacer para comparar bien dos textos?", "Mirar los mismos aspectos en ambos", "Así la comparación es justa."),
   E("¿Cómo se justifica una preferencia?", "Con «porque» y un ejemplo", "Sin ejemplo no hay justificación."),
   E("¿Dos lectores pueden preferir textos distintos?", "Sí, si justifican", "La preferencia es personal.")],
  (f"Lee: «{TEXTO_A}» «{TEXTO_B}» Escribe una semejanza, dos diferencias y cuál prefieres justificando con un ejemplo del texto.", "Semejanza: ambos cuentan que Rosa encuentra a Canelo en la plaza. Diferencias: A usa lenguaje sencillo, B usa comparaciones; A termina volviendo a casa, B con un abrazo. Prefiero el B porque dice que la lluvia golpeaba como un tambor y así la imagino.", ["escribe una semejanza", "escribe dos diferencias", "justifica su preferencia con ejemplo"], ["comparación escrita"], ["comparar aspectos distintos", "no justificar"], "Cambia tu preferencia y escribe la justificación contraria."),
  "Compara dos cuentos que conozcas en un cuadro de semejanzas y diferencias.",
  "Escribe tu propia versión de un final distinto para el texto A.")

L(OA4, 7,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a aplicar juntas las herramientas de análisis a una narración nueva: lenguaje figurado, acciones de los personajes, consecuencias, ambiente y características.",
  ["Interpreto lenguaje figurado.", "Opino con ejemplos.", "Determino consecuencias y ambiente.", "Describo personajes."],
  ["Al analizar una narración nueva puedes recorrer una lista de preguntas: ¿qué lenguaje figurado aparece y qué significa?, ¿cómo son los personajes y qué hacen?, ¿qué consecuencias tienen sus acciones?, ¿cuál es el ambiente y qué costumbres se ven?, ¿qué pienso yo y en qué parte del texto me baso?",
   "No necesitas responder todo con la misma extensión. Elige lo más importante para la historia. Si el cuento trata de superar el miedo, las acciones del personaje y las consecuencias son más relevantes que el color de su ropa. Siempre respalda tus respuestas con un ejemplo del texto.",
   "Al final, junta tus ideas en pocas frases: de qué trata la historia, cómo cambia el personaje y qué opinas. Así demuestras que comprendiste el texto en profundidad."],
  [("analizar", "examinar las partes de un texto para comprenderlo mejor"), ("transferir", "usar lo aprendido en una situación nueva"), ("respaldar", "apoyar con una prueba o ejemplo"), ("síntesis", "resumen de las ideas más importantes")],
  [("Analizar con ejemplos", f"Lees: «{FARO}» ¿Cómo es Nico por dentro y qué ejemplo lo muestra?", ["Busco lo que hace: vuelve a encender la luz tres veces.", "Aunque tenía miedo, no se rindió.", "Es perseverante."], "Perseverante: encendió la lámpara tres veces pese al miedo"),
   ("Consecuencia y cambio", "¿Qué consecuencia tuvo la luz encendida y cómo cambió Nico?", ["El bote de Ramón encontró el camino.", "Nico dejó de temer a las tormentas.", "Se sintió orgulloso de su tarea."], "El bote se orientó y Nico perdió el miedo")],
  [("Responder una pregunta sin mirar el texto.", "Se confía en la memoria.", "Vuelve al texto y busca la prueba."), ("Analizar solo un aspecto.", "Se elige lo más fácil.", "Revisa las cinco preguntas de la lista.")],
  ([E(FARO + " ¿Quién vivía junto al faro?", "Nico", "Lo dice la primera oración."),
    E(FARO + " ¿Qué hacía Nico cada noche?", "Subía a encender la luz", "El texto lo dice."),
    E(FARO + " ¿Qué apagó la lámpara una noche?", "El viento", "Lo dice la segunda oración.")],
   [E(FARO + " ¿Cuántas veces volvió a encender Nico la lámpara después de que el viento la apagó?", "Tres", "Lo dice la tercera oración: «volvió a encenderla tres veces»."),
    E(FARO + " ¿Qué sentía Nico cuando encendía la luz con manos temblorosas?", "Miedo", "Los temblores lo sugieren."),
    E(FARO + " ¿Quién contó a Nico lo ocurrido al amanecer?", "El pescador Ramón", "Le contó cómo su bote se orientó.")],
   [E(FARO + " «Con las manos temblorosas» muestra que Nico sentía miedo, pero igual actuó. ¿Qué característica psicológica muestra?", "Valentía o perseverancia", "Actuó a pesar del miedo."),
    E(FARO + " ¿Cuál es el ambiente del texto: una noche de tormenta junto al mar o una mañana en una ciudad?", "Una noche de tormenta junto al mar", "El faro, el mar y la tormenta lo muestran."),
    E(FARO + " ¿Qué consecuencia tuvo que la luz quedara prendida?", "El bote de Ramón encontró el camino", "Fue guiado por la luz.")],
   [E(FARO + " Ana dice que Nico es cobarde porque tenía miedo. Beto dice que es valiente porque encendió la luz pese al miedo. ¿Quién fundamenta mejor con el texto?", "Beto", "Da la acción que lo muestra."),
    E(FARO + " ¿Cuál fue la consecuencia en Nico a largo plazo: dejó de temer a las tormentas o dejó de subir al faro?", "Dejó de temer a las tormentas", "El texto lo dice.")],
   [E(FARO + " Si Nico no hubiera vuelto a encender la lámpara, ¿qué podría haberle pasado al bote de Ramón?", "Podría haberse perdido", "Sin la luz no habría encontrado el camino."),
    E(FARO + " ¿Cuál es la mejor síntesis: (a) Nico vivía junto al faro. (b) Nico enfrenta su miedo, mantiene la luz encendida en una tormenta y ayuda a un pescador a orientarse. (c) Hubo una tormenta.", "(b)", "Reúne el hecho central, la ayuda y el cambio.")]),
  [E("Un compañero, nervioso, repite su exposición tres veces hasta que le sale bien. ¿Qué característica psicológica muestra: perseverancia o descuido?", "Perseverancia", "Insiste hasta lograrlo.")],
  [E("¿Qué es analizar un texto?", "Examinar sus partes para comprenderlo mejor", "Se revisa personajes, ambiente y hechos."),
   E("¿Dónde debes buscar el respaldo de tus respuestas?", "En el texto", "Allí están las pruebas."),
   E("¿Qué incluye una síntesis: las ideas más importantes o cada detalle?", "Las ideas más importantes", "Resume lo central.")],
  (f"Lee: «{FARO}» Escribe: 1) una expresión que ayude a imaginar el ambiente; 2) cómo es Nico por dentro, con un ejemplo; 3) una consecuencia de sus acciones; 4) tu opinión sobre Nico con «porque».", "1) «una tormenta cubrió el mar». 2) Valiente: volvió a encender la lámpara tres veces con las manos temblorosas. 3) El bote de Ramón encontró el camino. 4) Nico fue admirable porque no se rindió.", ["responde los cuatro puntos", "usa ejemplos del texto", "opina con «porque»"], ["cuatro respuestas"], ["responder sin ejemplo", "inventar hechos"], "Revisa si cada respuesta tiene un ejemplo del texto."),
  "Aplica la lista de cinco preguntas a un cuento que ya leíste.",
  "Escribe un texto breve con un personaje que supere un miedo y subraya las partes del análisis.")
